from pathlib import Path


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Anchor not found: {label}")
    return text.replace(old, new, 1)

# main.js
p = Path("src/main/main.js")
t = p.read_text(encoding="utf-8")

t = replace_once(
    t,
    '''const {\n    app,\n    BrowserWindow,\n    ipcMain,\n    dialog\n} = require("electron");''',
    '''const {\n    app,\n    BrowserWindow,\n    ipcMain,\n    dialog,\n    nativeImage\n} = require("electron");''',
    "electron nativeImage import",
)

anchor = '''function registerIpcHandlers() {'''
helper = '''function validateWatermarkImage(filePath) {\n    if (typeof filePath !== "string" || !filePath) {\n        throw new Error("Arquivo de marca d'água inválido.");\n    }\n\n    if (!fs.existsSync(filePath)) {\n        throw new Error("A imagem selecionada não foi encontrada.");\n    }\n\n    const extension = path.extname(filePath).toLowerCase();\n    if (![".png", ".webp", ".jpg", ".jpeg"].includes(extension)) {\n        throw new Error("Formato de imagem não suportado.");\n    }\n\n    const stat = fs.statSync(filePath);\n    const maxFileBytes = 25 * 1024 * 1024;\n    if (!stat.isFile() || stat.size <= 0) {\n        throw new Error("O arquivo selecionado não é uma imagem válida.");\n    }\n    if (stat.size > maxFileBytes) {\n        throw new Error("A marca d'água deve ter no máximo 25 MB.");\n    }\n\n    const image = nativeImage.createFromPath(filePath);\n    if (!image || image.isEmpty()) {\n        throw new Error("Não foi possível decodificar a imagem selecionada.");\n    }\n\n    const size = image.getSize();\n    const maxDimension = 8192;\n    const maxPixels = 32000000;\n    if (\n        size.width <= 0 ||\n        size.height <= 0 ||\n        size.width > maxDimension ||\n        size.height > maxDimension ||\n        size.width * size.height > maxPixels\n    ) {\n        throw new Error(\n            `Imagem grande demais (${size.width}x${size.height}). Use até 8192 px por lado.`\n        );\n    }\n\n    return {\n        filePath,\n        width: size.width,\n        height: size.height,\n        fileSize: stat.size\n    };\n}\n\n'''
if "function validateWatermarkImage" not in t:
    t = replace_once(t, anchor, helper + anchor, "watermark validation helper")

old = '''    ipcMain.handle(\n        "watermark:select",\n        async () => {\n            const result =\n                await dialog.showOpenDialog({\n                    title:\n                        "Selecionar marca d'água",\n                    properties: [\n                        "openFile"\n                    ],\n                    filters: [\n                        {\n                            name: "Imagens",\n                            extensions: [\n                                "png",\n                                "webp",\n                                "jpg",\n                                "jpeg"\n                            ]\n                        }\n                    ]\n                });\n\n            if (\n                result.canceled ||\n                result.filePaths.length === 0\n            ) {\n                return {\n                    ok: false,\n                    canceled: true\n                };\n            }\n\n            const current =\n                getSettings().watermarkStyle;\n\n            return {\n                ok: true,\n                watermarkStyle:\n                    updateWatermarkStyle({\n                        ...current,\n                        filePath:\n                            result.filePaths[0]\n                    })\n            };\n        }\n    );\n\n    ipcMain.handle(\n        "settings:set-watermark-style",\n        async (_event, style) => ({\n            ok: true,\n            watermarkStyle:\n                updateWatermarkStyle(style)\n        })\n    );'''

new = '''    ipcMain.handle(\n        "watermark:select",\n        async () => {\n            try {\n                const result =\n                    await dialog.showOpenDialog(\n                        mainWindow ?? undefined,\n                        {\n                            title:\n                                "Selecionar marca d'água",\n                            properties: [\n                                "openFile"\n                            ],\n                            filters: [\n                                {\n                                    name: "Imagens",\n                                    extensions: [\n                                        "png",\n                                        "webp",\n                                        "jpg",\n                                        "jpeg"\n                                    ]\n                                }\n                            ]\n                        }\n                    );\n\n                if (\n                    result.canceled ||\n                    result.filePaths.length === 0\n                ) {\n                    return {\n                        ok: false,\n                        canceled: true\n                    };\n                }\n\n                const validation =\n                    validateWatermarkImage(\n                        result.filePaths[0]\n                    );\n\n                return {\n                    ok: true,\n                    filePath: validation.filePath,\n                    image: {\n                        width: validation.width,\n                        height: validation.height,\n                        fileSize: validation.fileSize\n                    }\n                };\n            } catch (error) {\n                console.error(\n                    "Falha ao selecionar marca d'água:",\n                    error\n                );\n\n                return {\n                    ok: false,\n                    canceled: false,\n                    error:\n                        error instanceof Error\n                            ? error.message\n                            : "Não foi possível abrir a imagem."\n                };\n            }\n        }\n    );\n\n    ipcMain.handle(\n        "settings:set-watermark-style",\n        async (_event, style) => {\n            try {\n                if (style?.filePath) {\n                    validateWatermarkImage(\n                        style.filePath\n                    );\n                }\n\n                return {\n                    ok: true,\n                    watermarkStyle:\n                        updateWatermarkStyle(style)\n                };\n            } catch (error) {\n                console.error(\n                    "Falha ao salvar marca d'água:",\n                    error\n                );\n\n                return {\n                    ok: false,\n                    error:\n                        error instanceof Error\n                            ? error.message\n                            : "Não foi possível salvar a marca d'água."\n                };\n            }\n        }\n    );'''

t = replace_once(t, old, new, "safe watermark IPC handlers")
p.write_text(t, encoding="utf-8")

# WatermarkSettingsTab.tsx
p = Path("src/renderer/src/WatermarkSettingsTab.tsx")
t = p.read_text(encoding="utf-8")

old = '''            if (!result?.ok) {\n                return;\n            }\n\n            setDraft(result.watermarkStyle);\n            setStatus(\n                "Imagem selecionada. Ajuste tamanho e posição e salve."\n            );'''
new = '''            if (!result?.ok) {\n                if (!result?.canceled) {\n                    setStatus(\n                        result?.error ??\n                            "Não foi possível selecionar a imagem."\n                    );\n                }\n                return;\n            }\n\n            patch({\n                filePath: result.filePath\n            });\n            setStatus(\n                `Imagem validada${\n                    result.image\n                        ? ` (${result.image.width}x${result.image.height})`\n                        : ""\n                }. Ajuste tamanho e posição e salve.`\n            );'''
t = replace_once(t, old, new, "safe renderer selection")

old = '''            if (!result?.ok) {\n                throw new Error(\n                    "Falha ao salvar marca d'água."\n                );\n            }'''
new = '''            if (!result?.ok) {\n                throw new Error(\n                    result?.error ??\n                        "Falha ao salvar marca d'água."\n                );\n            }'''
t = replace_once(t, old, new, "surface save error")

old = '''                        <img\n                            src={\n                                (window as any).santtosAPI\n                                    .getMediaFileUrl(\n                                        draft.filePath\n                                    )\n                            }\n                            style={previewStyle}\n                            alt="Preview da marca d'água"\n                        />'''
new = '''                        <img\n                            src={\n                                (window as any).santtosAPI\n                                    .getMediaFileUrl(\n                                        draft.filePath\n                                    )\n                            }\n                            style={previewStyle}\n                            alt="Preview da marca d'água"\n                            onError={() =>\n                                setStatus(\n                                    "A imagem foi selecionada, mas o preview não conseguiu carregá-la. Tente PNG ou WebP."\n                                )\n                            }\n                        />'''
t = replace_once(t, old, new, "preview error handler")

p.write_text(t, encoding="utf-8")
print("safe watermark upload patch applied")
